<script setup>
import{onMounted,ref}from'vue';import{AlertTriangle,BadgeCheck,Bell,RefreshCw,RotateCcw,ShieldX}from'@lucide/vue';import{getCertificationLifecycle,readCertificationNotice,revokeCertification,scanCertifications}from'../api/certificationLifecycle';import{getM6EnterpriseWorkspace}from'../api/m6'
const organizationId=ref(''),data=ref(null),loading=ref(false),error=ref(''),busy=ref(''),reason=ref('岗位标准变更，需要重新完成能力复训')
async function init(){loading.value=true;error.value='';try{const m6=await getM6EnterpriseWorkspace();organizationId.value=m6.selected?.organization_id||m6.organizations?.[0]?.id||'';if(organizationId.value)await load()}catch(e){error.value=e.detail||'加载失败'}finally{loading.value=false}}
async function load(){if(!organizationId.value)return;data.value=await getCertificationLifecycle(organizationId.value)}
async function scan(){busy.value='scan';try{await scanCertifications(organizationId.value);await load()}catch(e){error.value=e.detail||'扫描失败'}finally{busy.value=''}}
async function revoke(cert){busy.value=cert.id;try{await revokeCertification(cert.id,{reason:reason.value,expected_version:cert.lock_version});await load()}catch(e){error.value=e.detail||'撤销失败'}finally{busy.value=''}}
async function read(n){await readCertificationNotice(n.id);await load()}
onMounted(init)
</script>
<template><main class="cert-page"><header><div><p>TRAINING GOVERNANCE</p><h2>认证生命周期与复训</h2><span>到期、撤销、复训与本地通知的可追责闭环</span></div><button aria-label="刷新认证生命周期" title="刷新" @click="load"><RefreshCw :size="16"/></button></header><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="empty">正在读取认证事实</div><template v-else-if="data"><section class="disclaimer"><AlertTriangle :size="16"/><div><strong>{{data.demo_role_disclaimer}}</strong><span>通知保证进入本地收件箱，不宣称邮件或短信已送达。</span></div></section><section class="toolbar"><span>组织 {{organizationId}} · 当前角色 {{data.role}}</span><button v-if="data.role!=='learner'" :disabled="Boolean(busy)" @click="scan"><RotateCcw :size="15"/>运行到期扫描</button></section><section class="grid"><article><BadgeCheck/><strong>{{data.certifications.length}}</strong><span>认证记录</span></article><article><RotateCcw/><strong>{{data.retraining_tasks.length}}</strong><span>复训任务</span></article><article><Bell/><strong>{{data.notifications.filter(x=>!x.read_at).length}}</strong><span>未读通知</span></article></section><section class="panel"><h3>认证与责任状态</h3><div v-for="cert in data.certifications" :key="cert.id" class="cert"><div><strong>{{cert.id}}</strong><span>{{cert.status}} · 版本 {{cert.lock_version}} · 到期 {{cert.expires_at||'长期有效'}}</span></div><div v-if="data.role!=='learner'&&cert.status==='active'" class="revoke"><input v-model="reason" aria-label="撤销原因"/><button :disabled="Boolean(busy)" @click="revoke(cert)"><ShieldX :size="14"/>撤销</button></div></div><p v-if="!data.certifications.length" class="empty">暂无认证记录</p></section><section class="split"><div class="panel"><h3>复训任务</h3><div v-for="task in data.retraining_tasks" :key="task.id" class="row"><div><strong>{{task.title}}</strong><span>{{task.trigger_type}} · 截止 {{task.due_at}}</span></div><em>{{task.status}}</em></div><p v-if="!data.retraining_tasks.length" class="empty">暂无复训任务</p></div><div class="panel"><h3>本地通知</h3><button v-for="n in data.notifications" :key="n.id" class="notice" :class="{unread:!n.read_at}" @click="read(n)"><div><strong>{{n.title}}</strong><span>{{n.body}}</span></div><em>{{n.read_at?'已读':'未读'}}</em></button><p v-if="!data.notifications.length" class="empty">暂无通知</p></div></section><section class="panel"><h3>不可变责任事件</h3><div v-for="e in data.events" :key="e.id" class="row"><div><strong>{{e.action}} · {{e.from_status}} → {{e.to_status}}</strong><span>{{e.actor_role}} · {{e.actor_public_id}} · {{e.reason}}</span></div><em>{{e.created_at}}</em></div><p v-if="!data.events.length" class="empty">暂无生命周期事件</p></section></template></main></template>
<style scoped>.cert-page{max-width:1200px;margin:0 auto;color:#27322c}.cert-page header,.toolbar,.disclaimer,.row,.cert,.revoke,.notice{display:flex;align-items:center}.cert-page header{justify-content:space-between;margin-bottom:14px}.cert-page header p{margin:0;color:#728279;font-size:10px;font-weight:800;letter-spacing:.12em}.cert-page h2{margin:4px 0;font-size:24px}.cert-page header span,.row span,.cert span,.notice span{display:block;color:#7b8980;font-size:10px}.cert-page header button{display:grid;width:36px;height:36px;place-items:center;border:1px solid #dce5de;border-radius:7px;background:#fff}.disclaimer{gap:9px;padding:11px;border-left:3px solid #c7a55c;background:#fff9ee}.disclaimer strong,.disclaimer span{display:block;font-size:11px}.disclaimer span{margin-top:3px;color:#776943}.toolbar{justify-content:space-between;margin:12px 0;font-size:11px}.toolbar button,.revoke button{display:flex;align-items:center;gap:5px;padding:8px 11px;border:0;border-radius:6px;background:#304237;color:#fff}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.grid article,.panel{min-width:0;border:1px solid #dfe7e1;border-radius:8px;background:#fff}.grid article{display:grid;grid-template-columns:22px 1fr;gap:3px 8px;padding:14px}.grid svg{grid-row:1/3}.grid strong{font-size:20px}.grid span{font-size:10px;color:#849188}.panel{margin-top:10px;padding:14px}.panel h3{margin:0 0 9px;font-size:12px}.cert,.row,.notice{min-width:0;justify-content:space-between;gap:12px;padding:10px;border-top:1px solid #e8eee9}.cert>div,.row>div,.notice>div{min-width:0}.cert strong,.row strong,.notice strong{font-size:11px}.revoke{gap:6px}.revoke input{width:260px;padding:7px;border:1px solid #dbe4dd;border-radius:6px;font-size:10px}.split{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px}.row em,.notice em{flex:0 0 auto;color:#617368;font-size:9px;font-style:normal}.notice{width:100%;background:transparent;text-align:left;border-right:0;border-bottom:0;border-left:0}.notice.unread{background:#f2f7f3}.empty{padding:25px;text-align:center;color:#89958d;font-size:11px}.error{padding:10px;background:#fff3f1;color:#944b43}@media(max-width:760px){.grid,.split{grid-template-columns:1fr}.cert{align-items:flex-start;flex-direction:column}.revoke{width:100%}.revoke input{min-width:0;flex:1}.toolbar{align-items:flex-start;gap:10px;flex-direction:column}.row,.notice{align-items:flex-start;flex-direction:column}.row em,.notice em{align-self:flex-start}.row span,.notice span{overflow-wrap:anywhere}}</style>
